    stats.nursery_allocations++; stats.nursery_payload_bytes += layout.words * sizeof(Word);
  }
  stats.allocation_header_bytes += sizeof(Header);
  stats.allocations++; stats.payload_bytes += layout.words * sizeof(Word);
