static void reclaim(Header *h) {
  size_t bytes = object_bytes(descriptor(h)->words);
  stats.old_live_bytes -= bytes; stats.old_live_payload_bytes -= bytes - sizeof(Header);
  stats.old_object_count--; stats.reclaimed_bytes += bytes;
